void DrawList::Triangle(Vec2 a,Vec2 b,Vec2 c,Color color){a=a+translation_;b=b+translation_;c=c+translation_;const uint32_t packed=PackColorRgba8(color);vertices.push_back({a.x,a.y,packed});vertices.push_back({b.x,b.y,packed});vertices.push_back({c.x,c.y,packed});}
void DrawList::WorldTriangle(Vec3 a,Vec3 b,Vec3 c,Color color){const uint32_t base=uint32_t(worldVertices.size()),packed=PackColorRgba8(color),normal=PackNormalSnorm8(Normalize(Cross(b-a,c-a)));worldVertices.push_back({a.x,a.y,a.z,normal,packed});worldVertices.push_back({b.x,b.y,b.z,normal,packed});worldVertices.push_back({c.x,c.y,c.z,normal,packed});worldIndices.insert(worldIndices.end(),{base,base+1,base+2});}
void DrawList::Quad(Vec2 c,Vec2 s,Color col){Vec2 a{c.x-s.x*.5f,c.y-s.y*.5f},b{c.x+s.x*.5f,c.y-s.y*.5f},d{c.x-s.x*.5f,c.y+s.y*.5f},e{c.x+s.x*.5f,c.y+s.y*.5f};Triangle(a,b,e,col);Triangle(a,e,d,col);}
void DrawList::Diamond(Vec2 c,float rx,float ry,Color col){Triangle({c.x,c.y-ry},{c.x+rx,c.y},{c.x,c.y+ry},col);Triangle({c.x,c.y-ry},{c.x,c.y+ry},{c.x-rx,c.y},col);}
void DrawList::IsoPrism(Vec2 c,float rx,float ry,float h,Color top,Color left,Color right){Vec2 t{c.x,c.y-ry-h},r{c.x+rx,c.y-h},b{c.x,c.y+ry-h},l{c.x-rx,c.y-h},bottom{c.x,c.y+ry},bottomLeft{c.x-rx,c.y},bottomRight{c.x+rx,c.y};Triangle(l,b,bottom,left);Triangle(l,bottom,bottomLeft,left);Triangle(b,r,bottomRight,right);Triangle(b,bottomRight,bottom,right);Triangle(t,r,b,top);Triangle(t,b,l,top);}
void DrawList::Ellipse(Vec2 c,float rx,float ry,Color col,int n){for(int i=0;i<n;i++){float a=float(i)*6.2831853f/n,b=float(i+1)*6.2831853f/n;Triangle(c,{c.x+std::cos(a)*rx,c.y+std::sin(a)*ry},{c.x+std::cos(b)*rx,c.y+std::sin(b)*ry},col);}}
void DrawList::ProjectedEllipseShadow(Vec2 base,float rx,float ry,Vec2 lightDirection,float height,float opacity,int segments){const Vec2 direction=Normalize(lightDirection);Ellipse(base+direction*(std::max)(0.f,height),(std::max)(0.f,rx),(std::max)(0.f,ry),{0,0,0,Clamp(opacity,0.f,1.f)},segments);}
void DrawList::Circle(Vec2 c,float r,Color col,int n){Ellipse(c,r,r,col,n);}
void DrawList::Line(Vec2 a,Vec2 b,float w,Color col){Vec2 n=Normalize(Vec2{-(b.y-a.y),b.x-a.x})*(w*.5f);Triangle(a+n,b+n,b-n,col);Triangle(a+n,b-n,a-n,col);}

