void D3D12Renderer::DestroyMesh(MeshHandle3D handle){if(!impl_||!handle)return;auto& d=*impl_;auto found=d.residentMeshes.find(handle.value);if(found==d.residentMeshes.end())return;d.Flush();d.stats.residentMeshBytes-=found->second.bytes;d.residentMeshes.erase(found);d.instanceGroups.erase(handle.value);d.overlayInstanceGroups.erase(handle.value);d.stats.residentMeshes=d.residentMeshes.size();}

