 const unsigned rw=useDLSS?d.dlss.RenderWidth():d.width,rh=useDLSS?d.dlss.RenderHeight():d.height;const CanvasViewport canvas=CalculateCanvasViewport({float(d.logicalWidth),float(d.logicalHeight)},{float(rw),float(rh)});D3D12_VIEWPORT vp{canvas.x,canvas.y,canvas.width,canvas.height,0,1};D3D12_RECT sr{LONG(canvas.x),LONG(canvas.y),LONG(canvas.x+canvas.width),LONG(canvas.y+canvas.height)};d.list->RSSetViewports(1,&vp);d.list->RSSetScissorRects(1,&sr);d.list->SetGraphicsRootSignature(d.root.Get());d.list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);if((worldCount&&worldIndexCount)||!d.activeMeshGroups.empty()||!d.activeOverlayMeshGroups.empty()){const DirectionalLight3D& light=dl.DirectionalLight();const Atmosphere3D& atmosphere=dl.Atmosphere();const float directionAmbient[4]={light.direction.x,light.direction.y,light.direction.z,light.ambient},colorIntensity[4]={light.color.r,light.color.g,light.color.b,light.intensity},fogColor[4]={atmosphere.fogColor.r,atmosphere.fogColor.g,atmosphere.fogColor.b,atmosphere.fogColor.a},cameraFogStart[4]={atmosphere.cameraPosition.x,atmosphere.cameraPosition.y,atmosphere.cameraPosition.z,atmosphere.fogStart},fogEndEnabled[4]={atmosphere.fogEnd,atmosphere.enabled?1.f:0.f,0,0};d.list->SetGraphicsRoot32BitConstants(0,16,&dl.ViewProjection().values[0][0],0);d.list->SetGraphicsRoot32BitConstants(0,4,directionAmbient,16);d.list->SetGraphicsRoot32BitConstants(0,4,colorIntensity,20);d.list->SetGraphicsRoot32BitConstants(0,4,fogColor,24);d.list->SetGraphicsRoot32BitConstants(0,4,cameraFogStart,28);d.list->SetGraphicsRoot32BitConstants(0,4,fogEndEnabled,32);}
